#pragma once
#include "rinkfit/joint_al.hpp"
#include <fstream>
namespace rinkfit {
struct JointCaptureCertifiedDomainV1 {
 struct Ref{std::string file,sha;};std::vector<Ref>refs;std::string manifest_sha,parent_token;std::map<std::string,std::array<double,2>>ranges;std::vector<double>scene;
 static JointCaptureCertifiedDomainV1 load(const JointEventModel&m,const eventio::Json&binding){
  JointCaptureCertifiedDomainV1 d;auto verified=[&](const eventio::Json&r){std::string f=r.at("file"),s=r.at("sha256");eventio::verify(f,s);d.refs.push_back({f,s});return f;};auto manifest=verified(binding);d.manifest_sha=binding.at("sha256");auto j=eventio::read_json(manifest);if(j.at("schema")!="rinkfit.capture_certified_numeric_domain.v1"||j.at("scene_policy")!="fixed_to_same_g0_scene"||j.at("direct_logf_shots")!=eventio::Json::array({"s02","s03","s04"}))throw std::runtime_error("unsupported capture certified numeric domain policy");
  auto mp=verified(j.at("parent_model")),cp=verified(j.at("parent_complete_checkpoint")),rp=verified(j.at("parent_native_g0_receipt"));auto ref=eventio::read_json(mp),receipt=eventio::read_json(rp);std::ifstream in(cp);auto state=read_checkpoint(in);d.parent_token=j.at("parent_state_token");if(state.state.token()!=d.parent_token||receipt.at("complete_state_token")!=d.parent_token||receipt.at("true_RS_constraint_debt").at("state_token")!=d.parent_token||receipt.at("true_RS_constraint_debt").at("g_max_positive").get<double>()!=0||receipt.at("true_RS_constraint_debt").at("h_max_abs").get<double>()!=0||receipt.at("model_sha256")!=j.at("parent_model").at("sha256"))throw std::runtime_error("certified numerical domain lacks same-token complete g0 parent");
  for(const char*key:{"source_clock","rigs","shots","linear_control_manifolds","physical_equalities"}){if(ref.contains(key)!=m.source_json.contains(key)||(ref.contains(key)&&ref.at(key)!=m.source_json.at(key)))throw std::runtime_error(std::string("capture fixed projection/layout metadata changed: ")+key);}
  std::map<std::string,std::vector<double>>parameters;for(const auto&p:state.state.data().parameters)parameters[p.name]=p.values;d.scene=parameters.at(m.blocks.at(m.scene_block).name);if(d.scene.size()!=5||m.blocks.at(m.scene_block).values!=d.scene)throw std::runtime_error("capture requires the one unchanged g0 scene");
  for(const auto&r:m.rigs){const auto&v=parameters.at("rig/"+r.id+"/numerical_zoom_enclosure");if(v.size()!=2||!std::isfinite(v[0])||!std::isfinite(v[1])||v[0]>v[1])throw std::runtime_error("invalid parent certified zoom enclosure");d.ranges[r.id]={v[0],v[1]};}
  if(d.ranges.size()!=3)throw std::runtime_error("capture certified domain requires the same three rigs");return d;
 }
 void assert_dependencies()const{for(const auto&r:refs)eventio::verify(r.file,r.sha);}
 eventio::Json bind_auxiliary(JointALBuilder&b)const{assert_dependencies();const auto before=b.capture_state().token();eventio::Json changed=eventio::Json::array();for(auto v:b.parameter_blocks())for(const auto&entry:ranges)if(v.name=="rig/"+entry.first+"/numerical_zoom_enclosure"){if(v.size!=2)throw std::runtime_error("zoom enclosure parameter size");changed.push_back({{"name",v.name},{"before",std::vector<double>(v.data,v.data+2)},{"after",entry.second}});v.data[0]=entry.second[0];v.data[1]=entry.second[1];}return {{"schema","rinkfit.capture_certified_numeric_domain_aux_binding.v1"},{"policy_identity",manifest_sha},{"parent_state_token",parent_token},{"before_token",before},{"after_token",b.capture_state().token()},{"physical_model_or_source_changed",false},{"numerical_enclosures",changed}};}
 eventio::Json install(JointALBuilder&b,ceres::Problem&p)const{
  assert_dependencies();if(b.core.model.blocks.at(b.core.model.scene_block).values!=scene)throw std::runtime_error("one common capture scene moved from certified g0 value");auto*sp=b.core.model.blocks.at(b.core.model.scene_block).values.data();if(!p.HasParameterBlock(sp))throw std::runtime_error("capture scene missing from actual graph");p.SetParameterBlockConstant(sp);eventio::Json hulls=eventio::Json::array(),controls=eventio::Json::array(),fixed_affine=eventio::Json::array();
  for(auto v:b.parameter_blocks())for(const auto&entry:ranges)if(v.name=="rig/"+entry.first+"/numerical_zoom_enclosure"){if(v.size!=2||v.data[0]!=entry.second[0]||v.data[1]!=entry.second[1]||!p.HasParameterBlock(v.data))throw std::runtime_error("capture certified enclosure was not bound before graph construction");p.SetParameterBlockConstant(v.data);hulls.push_back({{"rig",entry.first},{"range",entry.second},{"actual_Ceres_constant",p.IsParameterBlockConstant(v.data)}});}
  std::set<int>affine;for(const auto&x:b.core.model.source_json.value("linear_control_manifolds",eventio::Json::array()))affine.insert(x.at("block").get<int>());std::set<std::pair<int,int>>done;
  for(const auto&s:b.core.model.shots){const auto range=ranges.at(s.rig_id);if(s.id=="s01"){for(int bi:s.control_sources){auto&v=b.core.model.blocks.at(bi);if(!p.HasParameterBlock(v.values.data())||!p.IsParameterBlockConstant(v.values.data()))throw std::runtime_error("S01 authoritative affine/fine motion must remain constant in capture v3");}fixed_affine.push_back({{"shot",s.id},{"authoritative_source_blocks_constant",true},{"direct_scalar_bounds_not_applied_to_affine_coordinates",true}});continue;}if(s.id!="s02"&&s.id!="s03"&&s.id!="s04")throw std::runtime_error("capture direct logf scope changed");if(b.core.model.source_json.at("shots").at(s.id).contains("control_coordinates"))throw std::runtime_error("non-S01 control coordinate map is not qualified as direct logf");
   for(std::size_t k=0;k<s.control_sources.size();++k){int bi=s.control_sources[k],off=s.control_offsets[k];auto&v=b.core.model.blocks.at(bi);if(bi!=s.control_blocks[k]||off!=0||v.values.size()!=3||affine.count(bi)||v.name!="shot/"+s.id+"/control/"+std::to_string(k))throw std::runtime_error("direct logf hard bound rejected an affine/aliased control");if(!done.insert({bi,2}).second)continue;double lo=std::max(v.lower.at(2),range[0]),hi=std::min(v.upper.at(2),range[1]);if(!(lo<=hi)||v.values[2]<lo||v.values[2]>hi)throw std::runtime_error("capture control logf is outside existing certified domain: "+v.name);auto*x=v.values.data();if(!p.HasParameterBlock(x))throw std::runtime_error("actual direct logf control missing from graph");p.SetParameterLowerBound(x,2,lo);p.SetParameterUpperBound(x,2,hi);if(p.GetParameterLowerBound(x,2)!=lo||p.GetParameterUpperBound(x,2)!=hi)throw std::runtime_error("actual Ceres logf bounds differ");controls.push_back({{"shot",s.id},{"block",bi},{"name",v.name},{"ambient_index",2},{"lower",lo},{"upper",hi},{"current",v.values[2]},{"constant",p.IsParameterBlockConstant(x)}});}
  }
  return {{"schema","rinkfit.actual_capture_certified_numeric_domain.v1"},{"policy_identity",manifest_sha},{"parent_state_token",parent_token},{"scene_block",b.core.model.scene_block},{"scene_constant",p.IsParameterBlockConstant(sp)},{"scene_values",scene},{"fixed_certified_zoom_enclosures",hulls},{"direct_control_bounds",controls},{"fixed_affine_scope",fixed_affine},{"source_UV_or_model_parameter_boxes_changed",false},{"certificate_expanded",false},{"Brown_coefficients_modified",false}};
 }
};
}
